zig_test:
test "t13 process stdout" {
    const ok = try captureChildStdout(std.testing.allocator, std.testing.io, &.{ "/usr/bin/sh", "-c", "printf 'hola'" });
    defer std.testing.allocator.free(ok);
    try std.testing.expectEqualStrings("hola", ok);
    try std.testing.expectError(error.ChildFailed, captureChildStdout(std.testing.allocator, std.testing.io, &.{ "/usr/bin/sh", "-c", "printf 'x'; exit 3" }));
}
